import { cn } from "@/lib/utils";

// Official Google Workspace Gmail high-DPI logo (440x350)
const GMAIL_ICON_DATA_URI = "data:image/png;base64,";

export function GmailIcon({ className }: { className?: string }) {
  return (
    <svg
      className={cn("w-4 h-4 shrink-0", className)}
      viewBox="0 0 440 350"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
    >
      <image href={GMAIL_ICON_DATA_URI} width="440" height="350" />
    </svg>
  );
}
